t:34px;border-radius:10px;background:#fff0dc;color:#bd7813;display:grid;place-items:center}.mockrow:nth-child(3) .mockicon{background:#e7efff;color:var(--blue)}.mockrow:nth-child(4) .mockicon{background:#e3f8ef;color:var(--green)}.mockrow strong{font-size:11px;display:block}.mockrow small{font-size:10px;color:var(--muted)}.pill{margin-left:auto;border-radius:20px;background:#fff1d6;color:#a36a0b;padding:6px 8px;font-size:9px;font-weight:800;white-space:nowrap}.pill.blue{background:#eaf0ff;color:var(--blue)}.pill.green{background:#e5f8ef;color:var(--green)}.float-note{position:absolute;right:-22px;bottom:44px;background:#fff;padding:14px 17px;border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow);font-size:11px}.float-note b{display:block;font-size:13px;margin-bottom:4px}.section{padding:86px 0}.section-soft{background:var(--bg)}.center{text-align:center}.kicker{font-size:11px;color:var(--blue);font-weight:800;letter-spacing:1.8px;text-transform:uppercase}.section h2{font-size:clamp(28px,3vw,40px);letter-spacing:-1.5px;line-height:1.2;margin:13px 0 14px}.section-intro{max-width:650px;margin:0 auto;color:var(--muted);font-size:14px;line-height:1.9}.features{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:40px}.feature{background:#fff;border:1px solid var(--line);border-radius:20px;padding:27px;transition:.25s}.feature:hover{transform:translateY(-5px);box-shadow:var(--shadow);border-color:#cbd9ff}.feature-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:15px;background:var(--pale);color:var(--blue);font-size:21px}.feature h3{font-size:16px;margin:20px 0 10px}.feature p{font-size:12px;line-height:1.8;color:var(--muted);margin:0}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:42px;text-align:left}.step{position:relative;padding:25px 21px;background:#fff;border:1px solid var(--line);border-radius:18px}.stepnum{font-size:11px;font-weight:800;color:var(--blue);background:var(--pale);width:34px;height:34px;border-radius:11px;display:grid;place-items:center}.step h3{font-size:14px;margin:18px 0 8px}.step p{font-size:11px;line-height:1.8;color:var(--muted);margin:0}.step:not(:last-child):after{content:'→';position:absolute;right:-17px;top:35px;z-index:2;background:#fff;border:1px solid var(--line);border-radius:50%;width:30px;height:30px;display:grid;place-items:center;color:var(--blue);font-weight:800}.workflow{display:grid;grid-template-columns:.8fr 1.2fr;gap:48px;align-items:center;margin-top:42px}.workflow-copy p{color:var(--muted);font-size:13px;line-height:1.9}.workflow-list{display:grid;gap:12px}.wf{display:flex;align-items:center;gap:14px;padding:16px;border:1px solid var(--line);border-radius:15px;background:white}.wf-icon{width:38px;height:38px;display:grid;place-items:center;background:var(--pale);color:var(--blue);border-radius:12px}.wf strong{font-size:12px;display:block}.wf small{font-size:11px;color:var(--muted)}.wf-arrow{margin-left:auto;color:#94a3b8}.cta{padding:0 0 85px}.cta-box{background:linear-gradient(120deg,#14294e,#234ba8);border-radius:25px;padding:43px 48px;color:white;display:flex;align-items:center;justify-content:space-between;gap:25px;overflow:hidden;position:relative}.cta-box:after{content:'';position:absolute;width:280px;height:280px;border:1px solid #ffffff20;border-radius:50%;right:120px;top:-180px;box-shadow:0 0 0 35px #ffffff08,0 0 0 70px #ffffff06}.cta h2{font-size:27px;letter-spacing:-1px;margin:0 0 10px;position:relative;z-index:1}.cta p{color:#c6d5f6;font-size:12px;margin:0;position:relative;z-index:1}.cta .btn{position:relative;z-index:1;white-space:nowrap;background:white;color:#234ba8}.footer{border-top:1px solid var(--line);padding:27px 0;color:var(--muted);font-size:11px}.footer-inner{display:flex;justify-content:space-between;gap:20px;align-items:center}.footer-links{display:flex;gap:20px}.mobile-toggle{display:none;border:1px solid var(--line);background:white;border-radius:10px;padding:9px 12px;font-size:20px;color:var(--ink)}
@media(max-width:900px){.hero-grid{grid-template-columns:1fr;gap:42px}.hero-copy{max-width:720px}.mockup{max-width:600px;width:100%;margin:auto}.features{grid-template-columns:repeat(2,1fr)}.steps{grid-template-columns:repeat(2,1fr)}.step:nth-child(2):after{display:none}.workflow{grid-template-columns:1fr;gap:25px}.navlinks{gap:14px}.float-note{right:-8px}}
@media(max-width:620px){.wrap{width:min(100% - 28px,1160px)}.nav{height:68px}.brand{font-size:17px}.logo{width:38px;height:38px}.navlinks{display:none;position:absolute;top:68px;left:14px;right:14px;padding:17px;background:white;border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);flex-direction:column;align-items:stretch}.navlinks.open{display:flex}.navlinks a{padding:8px}.navactions .btn-light{display:none}.navactions .btn{padding:10px 12px;font-size:11px}.mobile-toggle{display:block}.hero{padding:55px 0 60px}.hero h1{letter-spacing:-1.7px;font-size:40px}.lead{font-size:13px}.hero-buttons .btn{flex:1;padding:13px 12px}.mockup{padding:10px;border-radius:18px}.stat{padding:10px}.stat b{font-size:20px}.float-note{right:0;bottom:15px}.section{padding:64px 0}.features,.steps{grid-template-columns:1fr}.step:after{display:none!important}.feature{padding:23px}.workflow{gap:20px}.cta-box{padding:30px 24px;align-items:flex-start;flex-direction:column}.cta h2{font-size:24px}.footer-inner{align-items:flex-start;flex-direction:column}.footer-links{flex-wrap:wrap;gap:13px}}
